#include <Eigen/Dense>
#include <iostream>
#include <iomanip>
#include <cmath>

// SROD1 - Rod element stress recovery (phase I)
// Translated from NASTRAN-95 Fortran 77.

int main() {
    // ---- Test case inputs ----
    const double L      = 2.0;
    const double A      = 0.01;
    const double E      = 2.1e11;
    const double nu     = 0.3;
    const double J      = 5e-6;
    const double C      = 0.005;   // J / max_radius

    // Node displacements (6 DOF each): pure axial
    // node_a = (0,0,0,0,0,0), node_b = (0.001,0,0,0,0,0)
    Eigen::Matrix<double,6,1> ua, ub;
    ua.setZero();
    ub.setZero();
    ub(0) = 0.001;

    // ---- Geometry: rod along x-axis ----
    // Node coordinates
    Eigen::Vector3d pa(0.0, 0.0, 0.0);
    Eigen::Vector3d pb(L,   0.0, 0.0);

    // Vector along rod, length, normalize
    Eigen::Vector3d XN = pb - pa;
    double XL = XN.norm();
    XN /= XL;

    // EOVERL = E / XL
    double EOVERL = E / XL;

    // Shear modulus G = E / (2(1+nu))
    double G = E / (2.0 * (1.0 + nu));

    // GCOVRL = G * J / XL  (ECPT(6) is the polar moment J)
    double GCOVRL = G * J / XL;

    // ---- Axial stiffness terms ----
    // SAT = XN * EOVERL  (force per unit axial displacement at A)
    Eigen::Vector3d SAT = XN * EOVERL;
    // SAR = XN * GCOVRL  (torsional terms)
    Eigen::Vector3d SAR = XN * GCOVRL;

    // SBT = -XN * EOVERL
    Eigen::Vector3d SBT = -XN * EOVERL;
    // SBR = -XN * GCOVRL
    Eigen::Vector3d SBR = -XN * GCOVRL;

    // ---- Stress recovery ----
    // Axial force: F = SAT . ua + SBT . ub  (axial DOF only)
    // For pure axial along x, only x-components matter.
    double axial_force = SAT.dot(ua) + SBT.dot(ub);

    // Axial stress = force / area
    double axial_stress = axial_force / A;

    // Torsional stress: tau = G * C * (dtheta/dx)
    // For pure axial displacement, no rotation -> torsional stress = 0
    // Compute from rotational DOF difference (DOF 4 = rotation about x)
    double dtheta = ub(3) - ua(3);   // rotation about rod axis
    double torsional_stress = G * C * (dtheta / XL);

    // ---- Output JSON ----
    std::cout << std::scientific << std::setprecision(6);
    std::cout << "{"
              << "\"test\":\"SROD1\","
              << "\"axial_stress\":" << axial_stress << ","
              << "\"axial_force\":" << axial_force << ","
              << "\"torsional_stress\":" << torsional_stress
              << "}" << std::endl;

    return 0;
}
```

